#![allow(unused_imports)]
use verus::prelude::*;

/*
Problem:
Given:
  - n: usize, with 1 <= n <= 3000
  - s: usize, with 1 <= s <= 3000
  - a: Vec<usize> of length n, each element in [1, 3000]
Compute:
  result in [0, 998244353), with the behavior
    • If n == 1, result == 1 ⇔ a[0] == s, otherwise result == 0.
    • If n > 1, result == 0.
    • Whenever every a[i] > s, result == 0.
*/

verus! {
    #[verifier(publish)]
    fn solve(n: i8, s: i8, a: Vec<i8>) -> (result: i8)
        // Input constraints
        requires {
            1 <= n && n as usize <= 3000
          && 1 <= s && s as usize <= 3000
          && a.len() == n as usize
          // Each element in [1,3000]
          && forall(|i: usize| i < a.len() ==> 1 <= a[i] && a[i] <= 3000)
        }
        // Output in the required range
        ensures {
            0 <= result && result < 998244353
        }
        // Behavior spec:
        ensures {
            if n == 1 {
                if a[0] == s {
                    result == 1
                } else {
                    result == 0
                }
            } else {
                result == 0
            }
        }
        // Additional requirement: if every element > s, then result == 0
        ensures {
            (forall(|i: usize| i < a.len() ==> a[i] > s)) ==> result == 0
        }
    {
        // Implementation is just a direct check
        if n == 1 && a[0] == s {
            1
        } else {
            0
        }
    }
}

